     "summary": "南财智讯8月5日电，科伦药业公告，公司控股股东刘革新先生近日将其持有的690.00万股股份质押给华泰证券（上海）资产管理有限公司，占其所持股份比例1.82%，占公司总股本比例0.43%，质押用途为个人资金需求；同时，刘革新先生解除质押916.70万股。本次质押后，刘革新先生累计质押股份数量为8902.00万股，占其所持股份比例23.48%，占公司总股本比例5.60%。（文章来源：南方财经网）",
