     "title": "外媒：美国拟禁止进口中国新型数据中心设备",
     "url": "http://finance.eastmoney.com/news/1345,202608043831468978.html",
     "time": "08-04 21:54",
     "ts": 1785851666,
     "summary": "据路透社4日报道，知情人士透露，美国政府正起草一项禁令，拟禁止进口中国新型号的数据中心组件，以保护支撑人工智能(AI)发展的关键基础设施。 四名知情人士称，负责监管美国电信行业的联邦通信委员会(FCC)正在制定相关措施，计划禁止进口中国新型号的光收发模块。光收发模块主要用于数据中心内部的高速光纤数据传输。 美国官员希望2026年内公布并实施禁令。 不过，知情人士称，FCC仍可能修改或搁置有关限制。 对此，中国驻美国大使馆回应称，北京敦促美国“倾听两国工商界客观、理性的声音”，",
